import { createServer } from "node:http";
import {
  createReadStream,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  statSync,
  writeFileSync,
  createWriteStream,
} from "node:fs";
import { createHash } from "node:crypto";
import { spawn } from "node:child_process";
import { dirname, extname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const prep = JSON.parse(readFileSync(join(root, "native-preparation.json"), "utf8"));
const project = prep.project;
const sourcePath = join(project, "小说原文", "斗破苍穹（原始文件）.txt");
const dist = join(root, "dist");
const port = 1489;
const MAX_BODY_BYTES = 35_000_000;
const IDLE_TIMEOUT_MS = 60_000;
const HARD_TIMEOUT_MS = 120_000;
const TERM_GRACE_MS = 5_000;
const allowedModes = new Set(["default", "chunk1000", "chunk1000cv", "textblocks100cv"]);

function parseArgs(argv) {
  const options = { mode: "default", lines: null, round: 1 };
  let index = 0;
  if (argv[0] && !argv[0].startsWith("--")) options.mode = argv[index++];
  while (index < argv.length) {
    const flag = argv[index++];
    const value = argv[index++];
    if (value === undefined || value.startsWith("--")) throw new Error(`Missing value for ${flag}`);
    if (flag === "--mode") options.mode = value;
    else if (flag === "--lines") options.lines = Number(value);
    else if (flag === "--round") options.round = Number(value);
    else throw new Error(`Unknown argument: ${flag}`);
  }
  if (!allowedModes.has(options.mode)) throw new Error(`Unknown mode: ${options.mode}`);
  if (options.lines !== null && (!Number.isSafeInteger(options.lines) || options.lines < 1)) {
    throw new Error("--lines must be a positive integer");
  }
  if (!Number.isSafeInteger(options.round) || options.round < 1) throw new Error("--round must be a positive integer");
  return options;
}

function takeLines(text, count) {
  if (count === null) return text;
  const breaks = /\r\n|\r|\n/g;
  let end = 0;
  for (let line = 0; line < count; line += 1) {
    const match = breaks.exec(text);
    if (!match) return text;
    end = breaks.lastIndex;
  }
  return text.slice(0, end);
}

function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function mimeType(path) {
  return ({
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".mjs": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".woff": "font/woff",
    ".woff2": "font/woff2",
    ".txt": "text/plain; charset=utf-8",
  })[extname(path).toLowerCase()] || "application/octet-stream";
}

function writeJson(path, value) {
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
}

function conciseReport(report) {
  const frontend = report?.frontend || {};
  const result = frontend.result || {};
  const phaseCounts = {};
  for (const event of frontend.events || []) {
    if (event.phase) phaseCounts[event.phase] = (phaseCounts[event.phase] || 0) + 1;
  }
  return {
    frontendStatus: frontend.status ?? null,
    resultStatus: result.status ?? null,
    mode: frontend.mode ?? frontend.config?.mode ?? null,
    source: result.source ? {
      chars: result.source.chars ?? null,
      utf8Bytes: result.source.utf8Bytes ?? null,
      sha256: result.source.sha256 ?? null,
    } : null,
    timings: result.timings ?? (frontend.measurements ? {mountSynchronousMs:frontend.measurements.mountSynchronousMs,mountToDoubleFrameMs:frontend.measurements.mountToDoubleFrameMs,finalSerializeMs:frontend.measurements.finalSerializeMs}:null),
    phaseCounts,
  };
}

function findForegroundRefusal(value, key = "") {
  if (value && typeof value === "object") {
    for (const [childKey, childValue] of Object.entries(value)) {
      const result = findForegroundRefusal(childValue, childKey);
      if (result) return result;
    }
  } else if (typeof value === "string") {
    const normalizedKey = key.toLowerCase();
    const text = value.toLowerCase();
    if (/(rejected[-_ ]foreground|foreground[-_ ](lost|rejected|refused|denied)|foreground.{0,30}lost)/i.test(value)) {
      return `${key}: ${value}`;
    }
    if (/status|stopreason/.test(normalizedKey) && /reject/.test(text) && /foreground/.test(text)) {
      return `${key}: ${value}`;
    }
    if (/(foreground|focus|activation)/.test(normalizedKey) && /(refus|denied|reject|not.?permitted|failed|unavailable)/.test(text)) {
      return `${key}: ${value}`;
    }
    if (/(foreground|activation).{0,60}(refus|denied|reject|not permitted|failed)/i.test(value)) return value;
  } else if (value === true && (/(foreground|activation).*(refus|denied|reject|failed)/i.test(key) || /foregroundlost/i.test(key))) {
    return `${key}: true`;
  }
  return null;
}

const options = parseArgs(process.argv.slice(2));
const novelBytes = readFileSync(sourcePath);
const novelText = novelBytes.toString("utf8");
const servedText = takeLines(novelText, options.lines);
const binary = prep.binary;
const htmlPath = join(dist, "index.html");
if (!existsSync(binary)) throw new Error(`Native validation binary not found: ${binary}`);
if (!existsSync(htmlPath)) throw new Error(`Static build not found: ${htmlPath}`);
if (!readFileSync(htmlPath, "utf8").includes("__CONFIG__")) throw new Error("dist/index.html is missing the __CONFIG__ placeholder");

const runsDir = join(root, "runs");
mkdirSync(runsDir, { recursive: true });
const label = `${options.mode}-${options.lines ?? "full"}-round${options.round}-`;
const runDir = mkdtempSync(join(runsDir, label));
const configDir = join(runDir, "config");
mkdirSync(configDir, { recursive: true });
const reportPath = join(runDir, "report.json");
const progressPath = join(runDir, "progress.jsonl");
const statusPath = join(runDir, "status.json");
const nativeLogPath = join(runDir, "native.log");
const config = { mode: options.mode, lines: options.lines, round: options.round };
const startedAt = Date.now();

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url || "/", `http://127.0.0.1:${port}`);
    const pathname = decodeURIComponent(url.pathname);
    if(pathname === "/native-focus") {
      const f=join(runDir,"native-focus.jsonl");
      const lines=existsSync(f)?readFileSync(f,"utf8").trim().split("\n"):[];
      res.setHeader("Content-Type","application/json");res.setHeader("Cache-Control","no-store");
      res.end(lines.length?lines.at(-1):JSON.stringify({foreground:false}));return;
    }
    if (pathname === "/save-check" && req.method === "POST") {
      const chunks = [];
      let length = 0;
      for await (const chunk of req) {
        length += chunk.length;
        if (length > MAX_BODY_BYTES) {
          res.statusCode = 413;
          res.end(JSON.stringify({ error: "body too large", limitBytes: MAX_BODY_BYTES }));
          return;
        }
        chunks.push(chunk);
      }
      const payload = JSON.parse(Buffer.concat(chunks).toString("utf8"));
      if (typeof payload.text !== "string") throw new Error("save-check requires a complete string field named text");
      const savedPath = join(runDir, `roundtrip-${options.round}.txt`);
      writeFileSync(savedPath, payload.text, "utf8");
      const readback = readFileSync(savedPath);
      const actualSha256 = sha256(readback);
      const textMatch = readback.toString("utf8") === payload.text;
      const hashMatch = typeof payload.expectedSha256 === "string" && actualSha256 === payload.expectedSha256;
      res.setHeader("Content-Type", "application/json; charset=utf-8");
      res.end(JSON.stringify({
        exactBytes: textMatch && hashMatch,
        textMatch,
        hashMatch,
        sha256: actualSha256,
        expectedSha256: payload.expectedSha256 ?? null,
        bytes: readback.length,
        scope: "Temporary Node filesystem roundtrip of complete text only; no application/native project save integration.",
      }));
      return;
    }

    if (req.method !== "GET" && req.method !== "HEAD") {
      res.statusCode = 405;
      res.end("Method not allowed");
      return;
    }
    if (pathname === "/novel.txt") {
      const requestedLines = url.searchParams.has("lines") ? Number(url.searchParams.get("lines")) : options.lines;
      const text = takeLines(novelText, Number.isSafeInteger(requestedLines) && requestedLines > 0 ? requestedLines : null);
      res.setHeader("Content-Type", "text/plain; charset=utf-8");
      res.setHeader("Cache-Control", "no-store");
      if (req.method === "HEAD") res.end();
      else res.end(text);
      return;
    }

    const requestedPath = pathname === "/" ? "index.html" : pathname.slice(1);
    const filePath = resolve(dist, requestedPath);
    if (filePath !== dist && !filePath.startsWith(`${dist}/`)) {
      res.statusCode = 403;
      res.end("Forbidden");
      return;
    }
    if (!existsSync(filePath) || !statSync(filePath).isFile()) {
      res.statusCode = 404;
      res.end("Not found");
      return;
    }
    res.setHeader("Cache-Control", "no-store");
    res.setHeader("Content-Type", mimeType(filePath));
    if (filePath === htmlPath) {
      const html = readFileSync(filePath, "utf8").replaceAll("__CONFIG__", JSON.stringify(config));
      res.setHeader("Content-Length", Buffer.byteLength(html));
      if (req.method === "HEAD") res.end();
      else res.end(html);
      return;
    }
    if (req.method === "HEAD") res.end();
    else createReadStream(filePath).pipe(res);
  } catch (error) {
    res.statusCode = 500;
    res.setHeader("Content-Type", "text/plain; charset=utf-8");
    res.end(String(error?.stack || error));
  }
});

await new Promise((resolveListen, rejectListen) => {
  server.once("error", rejectListen);
  server.listen(port, "127.0.0.1", resolveListen);
});

const logStream = createWriteStream(nativeLogPath, { flags: "a" });
await new Promise(resolve => setTimeout(resolve,4000));
const child = spawn(binary, [], {
  env: {
    ...process.env,
    LODESTORY_PERF_PROJECT: project,
    LODESTORY_PERF_CONFIG_DIR: configDir,
    LODESTORY_PERF_OUTPUT: reportPath,
    LODESTORY_PERF_PROGRESS: progressPath,
  },
  stdio: ["ignore", "pipe", "pipe"],
});
child.stdout.pipe(logStream, { end: false });
child.stderr.pipe(logStream, { end: false });

const focusStream=createWriteStream(join(runDir,"native-focus.jsonl"));
const focusMonitor=spawn(join(root,"focus-monitor"),[String(child.pid)],{stdio:["ignore","pipe","pipe"]});focusMonitor.stdout.pipe(focusStream,{end:false});
let watchdogReason = null;
let terminationTimer = null;
let hardTimer = null;
let lastProgressAt = Date.now();
let lastProgressBytes = 0;
let lastProgressLine = null;
let signalRequested = null;
let currentPhase = "native-starting";
let processExit = null;

function persistStatus(extra = {}) {
  writeJson(statusPath, {
    mode: options.mode,
    lines: options.lines,
    round: options.round,
    config,
    classification: "running",
    currentPhase,
    lastProgressLine,
    elapsedMs: Date.now() - startedAt,
    watchdogReason,
    runDir,
    ...extra,
  });
}

function terminate(reason) {
  if (watchdogReason || processExit) return;
  watchdogReason = reason;
  currentPhase = `watchdog-${reason}`;
  persistStatus();
  try {
    child.kill("SIGTERM");
  } catch {}
  terminationTimer = setTimeout(() => {
    if (!processExit) {
      try { child.kill("SIGKILL"); } catch {}
    }
  }, TERM_GRACE_MS);
}

persistStatus();
const watchdogTimer = setInterval(() => {
  const now = Date.now();
  if (existsSync(progressPath)) {
    try {
      const progressText = readFileSync(progressPath, "utf8");
      const bytes = Buffer.byteLength(progressText);
      if (bytes > lastProgressBytes) {
        lastProgressBytes = bytes;
        const lines = progressText.trimEnd().split("\n");
        const tail = lines.at(-1);
        try {
          lastProgressLine = JSON.parse(tail);
          if (lastProgressLine.phase) currentPhase = lastProgressLine.phase;
          if (lastProgressLine.mode === options.mode) lastProgressAt = now;
        } catch {
          lastProgressLine = tail?.slice(-500) || null;
        }
        persistStatus();
      }
    } catch {}
  }
  if (now - startedAt >= HARD_TIMEOUT_MS) terminate("global-120s");
  else if (now - lastProgressAt >= IDLE_TIMEOUT_MS) terminate("no-phase-progress-60s");
}, 500);
hardTimer = setTimeout(() => terminate("global-120s"), HARD_TIMEOUT_MS);

const handleSignal = (signal) => {
  if (signalRequested) return;
  signalRequested = signal;
  terminate(`runner-${signal.toLowerCase()}`);
};
process.on("SIGINT", handleSignal);
process.on("SIGTERM", handleSignal);

try {
  processExit = await new Promise((resolveExit, rejectExit) => {
    child.once("error", rejectExit);
    child.once("exit", (code, signal) => resolveExit({ code, signal }));
  });
} catch (error) {
  processExit = { code: null, signal: null, spawnError: String(error) };
} finally {
  focusMonitor.stdout.unpipe(focusStream);focusMonitor.kill("SIGTERM");focusStream.end();
  clearInterval(watchdogTimer);
  clearTimeout(hardTimer);
  clearTimeout(terminationTimer);
  process.off("SIGINT", handleSignal);
  process.off("SIGTERM", handleSignal);
  await new Promise((resolveClose) => server.close(resolveClose));
  logStream.end();
  await new Promise((resolveLog) => logStream.once("close", resolveLog));
}

let report = null;
let reportError = null;
if (existsSync(reportPath)) {
  try { report = JSON.parse(readFileSync(reportPath, "utf8")); }
  catch (error) { reportError = String(error); }
}
let progressEvents = [];
if (existsSync(progressPath)) {
  progressEvents = readFileSync(progressPath, "utf8").split(/\r?\n/).filter(Boolean).flatMap((line) => {
    try { return [JSON.parse(line)]; } catch { return []; }
  });
}

const finalEvent = [...(report?.frontend?.events || []), ...progressEvents]
  .filter((event) => event.phase === "complete")
  .at(-1);
const allEvidence = [report, ...progressEvents];
const foregroundRefusal = allEvidence.map((entry) => findForegroundRefusal(entry)).find(Boolean) || null;
const foregroundVerified = finalEvent?.hasFocus === true && finalEvent?.visibilityState === "visible";
let classification;
if (watchdogReason) classification = watchdogReason.startsWith("no-phase") || watchdogReason.startsWith("global") ? "timeout" : "interrupted";
else if (foregroundRefusal) classification = "foreground-refused";
else if (!processExit || processExit.spawnError || processExit.code !== 0 || processExit.signal) classification = "native-process-failed";
else if (reportError) classification = "invalid-report";
else if (!report) classification = "missing-report";
else if (report.frontend?.status !== "complete" || finalEvent?.phase !== "complete") classification = "incomplete";
else if (!foregroundVerified) classification = "foreground-unconfirmed";
else classification = "passed";

const focusSamples=existsSync(join(runDir,"native-focus.jsonl"))?readFileSync(join(runDir,"native-focus.jsonl"),"utf8").split("\n").filter(Boolean).flatMap(x=>{try{return[JSON.parse(x)]}catch{return[]}}):[];
const sourceEpoch=progressEvents.find(x=>x.phase==="source-ready")?.epochMs;
const finalEpoch=finalEvent?.epochMs??Date.now();
const measuredFocus=focusSamples.filter(x=>x.epochMs>=sourceEpoch&&x.epochMs<=finalEpoch);
const nativeForeground={sourceEpoch,finalEpoch,samples:measuredFocus.length,lostSamples:measuredFocus.filter(x=>!x.foreground).length,verified:measuredFocus.length>=3&&measuredFocus.every(x=>x.foreground)};
if(classification==="passed"&&!nativeForeground.verified)classification="native-foreground-unconfirmed";
const finalStatus = {
  nativeForeground,
  mode: options.mode,
  lines: options.lines,
  round: options.round,
  config,
  ...processExit,
  classification,
  passed: classification === "passed",
  passedMeaning: "Functional assertions and sampled foreground checks completed; no performance target is asserted.",
  foregroundVerified,
  foregroundRefusal,
  watchdogReason,
  elapsedMs: Date.now() - startedAt,
  reportError,
  reportSummary: report ? conciseReport(report) : null,
  runDir,
};
writeJson(statusPath, finalStatus);
console.log(JSON.stringify(finalStatus, null, 2));
if (classification !== "passed") process.exitCode = 1;

