import React from 'react';
import {createRoot} from 'react-dom/client';
import {flushSync} from 'react-dom';
import {createEditor,Editor,Node,Text,Transforms} from 'slate';
import {Slate,Editable,withReact,ReactEditor} from 'slate-react';
import {withHistory,HistoryEditor} from 'slate-history';

const config=window.__slateConfig;
const invoke=(command,args)=>window.__TAURI_INTERNALS__.invoke(command,args);
const viewport=document.getElementById('viewport');
const events=[],runtimeErrors=[],frames=[];
let sampling=false,foregroundLost=false,lastFrame=null,phase='startup',running=true;
const measurements={};
const countChanges={document:0,selection:0,beforeInput:0,input:0,trustedInput:0};
window.addEventListener('error',e=>runtimeErrors.push({message:e.message,phase}));
window.addEventListener('unhandledrejection',e=>runtimeErrors.push({message:String(e.reason),phase}));
window.addEventListener('blur',()=>{if(sampling)foregroundLost=true;});
document.addEventListener('visibilitychange',()=>{if(sampling&&document.visibilityState!=='visible')foregroundLost=true;});
const frame=t=>{if(sampling&&lastFrame!==null&&document.hasFocus()&&document.visibilityState==='visible')frames.push({phase,gapMs:t-lastFrame});lastFrame=t;if(running)requestAnimationFrame(frame);};
requestAnimationFrame(frame);
const now=()=>performance.now();
const normalize=s=>s.replace(/\r\n?/g,'\n');
const hash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),v=>v.toString(16).padStart(2,'0')).join('');
async function progress(next,detail={}){phase=next;const e={phase,atMs:now(),mode:config.mode,visible:document.visibilityState==='visible',visibilityState:document.visibilityState,hasFocus:document.hasFocus(),...detail};events.push(e);document.getElementById('progress').textContent=JSON.stringify(e);await invoke('desktop_perf_progress',{payload:e});}
function ticks(){return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('No foreground animation frame during '+phase)),5000);requestAnimationFrame(()=>requestAnimationFrame(()=>{clearTimeout(timeout);resolve();}));});}
function assert(value,message){if(!value)throw Error(message);}
function checkForeground(){assert(!foregroundLost&&document.hasFocus()&&document.visibilityState==='visible','Foreground was lost; discard this trial');}
function renderElement({attributes,children}){return <p {...attributes}>{children}</p>;}
function renderLeaf({attributes,children,leaf}){if(leaf.bold)children=<strong>{children}</strong>;return <span {...attributes} style={leaf.fontSize?{fontSize:leaf.fontSize}:undefined}>{children}</span>;}
function renderChunk({attributes,lowest,children}){return <div {...attributes} style={lowest&&config.mode==='chunk1000cv'?{contentVisibility:'auto'}:undefined}>{children}</div>;}
function serialize(editor){return editor.children.map(node=>Node.string(node)).join('\n');}
function historyClear(editor){editor.history.undos=[];editor.history.redos=[];}
function paragraphText(editor,index){return Node.string(editor.children[index]);}
function markerAt(text,offset,marker){return text.slice(0,offset)+marker+text.slice(offset);}

async function run(){
 await invoke('desktop_perf_focus');await ticks();checkForeground();
 const sourceStart=now();const response=await fetch('/novel.txt');assert(response.ok,'source fetch failed');const rawBytes=await response.arrayBuffer();const raw=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(rawBytes);
 const normalized=normalize(raw);const allLines=normalized.split('\n');
 const lines=config.lines?allLines.slice(0,config.lines):allLines;
 const expected=lines.join('\n');const expectedHash=await hash(expected);
 measurements.sourceFetchDecodeNormalizeHashMs=now()-sourceStart;
 measurements.source={rawUtf8Bytes:rawBytes.byteLength,rawUtf16Characters:raw.length,rawSha256:await hash(raw),modelUtf16Characters:expected.length,paragraphs:lines.length,fullNovel:!config.lines,normalizedSha256:expectedHash};
 measurements.cssContentVisibilitySupported=CSS.supports('content-visibility','auto');
 await progress('source-ready',measurements.source);sampling=true;lastFrame=null;await ticks();
 const modelStart=now();const value=lines.map(text=>({type:'paragraph',children:[{text}]}));measurements.modelBuildMs=now()-modelStart;
 const createStart=now();const editor=withReact(withHistory(createEditor()));if(config.mode!=='default')editor.getChunkSize=node=>Editor.isEditor(node)?1000:null;measurements.editorCreateMs=now()-createStart;
 const root=createRoot(document.getElementById('mount'));
 const changed=()=>{if(editor.operations.some(o=>o.type!=='set_selection'))countChanges.document++;else countChanges.selection++;};
 await progress('mount-start',{paragraphs:lines.length,modelBuildMs:measurements.modelBuildMs,editorCreateMs:measurements.editorCreateMs});
 const mountStart=now();flushSync(()=>root.render(<Slate editor={editor} initialValue={value} onChange={changed}><Editable id="editor" role="textbox" aria-label="Slate 超大文本临时编辑区" renderElement={renderElement} renderLeaf={renderLeaf} renderChunk={config.mode==='default'?undefined:renderChunk} spellCheck={false} autoCorrect="off" autoCapitalize="off" onBeforeInput={()=>countChanges.beforeInput++} onInput={e=>{countChanges.input++;if(e.nativeEvent.isTrusted)countChanges.trustedInput++;}} /></Slate>));
 measurements.mountSynchronousMs=now()-mountStart;
 await ticks();measurements.mountToDoubleFrameMs=now()-mountStart;
 const editable=document.getElementById('editor');assert(editable&&editable.isContentEditable,'Slate did not mount an editable region');editable.addEventListener('beforeinput',()=>countChanges.beforeInput++,true);editable.addEventListener('input',e=>{countChanges.input++;if(e.isTrusted)countChanges.trustedInput++;},true);
 measurements.dom={paragraphs:editable.querySelectorAll('[data-slate-node="element"]').length,allElements:editable.querySelectorAll('*').length,chunks:editable.querySelectorAll('[data-slate-chunk]').length};
 assert(measurements.dom.paragraphs===lines.length,'Rendered paragraph count differs from complete model');
 measurements.initialDocumentChangeCount=countChanges.document;measurements.initialScrollHeight=viewport.scrollHeight;
 await progress('mount-ready',{...measurements.dom,mountSynchronousMs:measurements.mountSynchronousMs,mountToDoubleFrameMs:measurements.mountToDoubleFrameMs,initialDocumentChanges:countChanges.document,scrollHeight:viewport.scrollHeight});checkForeground();
 const readStart=now();const initial=serialize(editor);measurements.initialFullTextReadMs=now()-readStart;measurements.initialFullTextExact=initial===expected;measurements.initialFullHashMatches=await hash(initial)===expectedHash;assert(measurements.initialFullTextExact&&measurements.initialFullHashMatches,'Initial full document content/hash mismatch');
 historyClear(editor);await progress('full-model-verified',{readMs:measurements.initialFullTextReadMs,hashMatches:true});
 const nonEmpty=[];for(let i=0;i<lines.length;i++)if(lines[i].length)nonEmpty.push(i);
 assert(nonEmpty.length>2,'source needs at least three nonempty lines');
 const locations=[nonEmpty[0],nonEmpty[Math.floor(nonEmpty.length/2)],nonEmpty[nonEmpty.length-1]];
 measurements.scroll=[];
 for(const [name,index] of [['start',locations[0]],['middle',locations[1]],['end',lines.length-1]]){
  await progress('scroll-'+name+'-start',{index});checkForeground();const dom=ReactEditor.toDOMNode(editor,editor.children[index]);const start=now();dom.scrollIntoView({block:name==='end'?'end':'center'});await ticks();
