import AppKit
import Foundation
import Darwin
let observerApplication = NSApplication.shared
observerApplication.setActivationPolicy(.prohibited)
let target = Int32(CommandLine.arguments[1])!
while kill(target, 0) == 0 {
    autoreleasepool {
        let front = NSWorkspace.shared.frontmostApplication?.processIdentifier ?? -1
        let payload: [String: Any] = ["epochMs": Date().timeIntervalSince1970 * 1000, "targetPid": target, "observerPid": ProcessInfo.processInfo.processIdentifier, "frontPid": front, "foreground": front == target]
        let data = try! JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys])
        FileHandle.standardOutput.write(data)
        FileHandle.standardOutput.write(Data([10]))
    }
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.25))
}
